        "矩形：面积 = 长 × 宽。三角形：面积 = 底 × 对应高 ÷ 2。一个长4厘米、宽3厘米的矩形面积为12平方厘米。一个底为4厘米、对应高为3厘米的三角形面积为6平方厘米。",
