        "3つの場所を心で訪ね、各場所に関連するアイテムを書き出します。",
        "アプリの既存の記憶の宮殿を使って、慣れ親しんだルートを作成するか、利用可能なルートを使う。最初は数か所から始め、それらが明確に区別できるか確認します。"
