        "分为三组：行动（植树）、效果（遮荫和蒸发）和需求（水分和根部空间）。大纲保留了它们之间的关系。",
        "不看原文，解释该行动、其运作方式以及所需条件。",
        "选择一段适合自己的简短说明性文字。写下三个引导问题，收起原文再回答。逐步增加篇幅。"
