        "逐字对比。纠正遗漏、顺序变化和额外添加的词语。",
        "练习下一段内容，然后练习段落之间的过渡。有时可以从中间开始。",
        "稍后不看原文，再次回忆。当当前部分记忆可靠时，延伸段落内容。",
        "早上我打开窗户。新鲜空气流入房间。然后我开始新的一天。",
        "三个句子是三个练习单元。先学第一句，再学第二句和它们之间的衔接。之后也试着从“新鲜空气……”开始回忆。",
        "尽可能准确地从记忆中写出这三个句子。",
        "选择一段你认为用词重要的短文。自己将其与原文对比；改写版本无法达到此特定目标。"
